import pytest


def is_palindrome(s):
    # Return True if s reads the same forwards and backwards
    return s == s[::-1]


@pytest.mark.parametrize('word,expected', [
    ('racecar', True),
    ('hello', False),
    ('madam', True),
    ('', True),
])
def test_is_palindrome(word, expected):
    assert is_palindrome(word) == expected


def _run_parametrized():
    passed = failed = 0
    for mark in getattr(test_is_palindrome, "pytestmark", []):
        if mark.name != "parametrize":
            continue
        for word, expected in mark.args[1]:
            try:
                test_is_palindrome(word, expected)
                passed += 1
            except AssertionError:
                failed += 1
    summary = f"{passed} passed"
    if failed:
        summary = f"{failed} failed, " + summary
    print(summary)


_run_parametrized()
